user nginx;
worker_processes auto;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    sendfile on;
    client_max_body_size 0;

    # タイムアウト設定
    keepalive_timeout 180;
    proxy_connect_timeout 180s;
    proxy_send_timeout 180s;
    proxy_read_timeout 180s;

    server {
        listen 8080;
        server_name localhost;

        port_in_redirect off;
        absolute_redirect off;

        # ログ設定
        access_log /var/log/nginx/nginx-access.log;
        error_log /var/log/nginx/nginx-error.log;
        access_log /dev/stdout;
        error_log /dev/stderr;

        # ------------------------------------------------------------
        # OAuth2 Proxy共通設定
        # ------------------------------------------------------------

        # OAuth2 ProxyがセットするCookieや認証情報が大きい場合に対応するための設定
        proxy_buffer_size 32k;
        proxy_buffers 8 16k;
        proxy_busy_buffers_size 64k;

        # OAuth2 Proxyから得られる認証情報を取得するために変数に格納するための設定
        auth_request_set $auth_user $upstream_http_x_auth_request_user;
        auth_request_set $auth_email $upstream_http_x_auth_request_email;
        auth_request_set $auth_preferred_username $upstream_http_x_auth_request_preferred_username;
        auth_request_set $groups $upstream_http_x_auth_request_groups;
        auth_request_set $access_token $upstream_http_x_auth_request_access_token;

        # 変数に格納した認証情報をヘッダーにセットするための設定
        proxy_set_header X-Forwarded-User $auth_user;
        proxy_set_header X-Forwarded-Email $auth_email;
        proxy_set_header X-Forwarded-Preferred-Username $auth_preferred_username;
        proxy_set_header X-Forwarded-groups $groups;
       proxy_set_header X-Forwarded-Access-Token $access_token;

        # 共通の proxy_set_header 設定
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;

        # WebSocket support (Streamlitアプリをリバースプロキシ連携するのに必要な設定)
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";

        # キャッシュ無効化設定
        proxy_cache off;
        proxy_no_cache 1;
        proxy_cache_bypass 1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
        add_header Expires "0";

        # ------------------------------------------------------------
        # OAuth2 Proxyのパス設定
        # ------------------------------------------------------------

        location /oauth2/ {
            proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/;
        }

        location = /oauth2/auth {
            proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/auth;
            proxy_pass_request_body off;
            proxy_set_header Content-Length "";
            proxy_set_header X-Original-URL $scheme://$http_host$request_uri;
        }

        location = /oauth2/sign_in {
            proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/sign_in;
        }

        location = /oauth2/callback {
            proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/callback;
        }

        # ------------------------------------------------------------
        # ログアウト設定
        # ------------------------------------------------------------

        location = /logout {
            return 302 ${ENV_KEYCLOAK_URL}realms/${ENV_KEYCLOAK_REALM}/protocol/openid-connect/logout?client_id=${ENV_KEYCLOAK_OIDC_CLIENT_ID}&post_logout_redirect_uri=${ENV_NGINX_URL}logout/after;
        }

        location = /logout/after {
            return 302 ${ENV_NGINX_URL}oauth2/sign_out;
        }

        # ------------------------------------------------------------
        # アプリケーションルーティング設定
        # ------------------------------------------------------------

        location / {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://app-portal:8080/;
        }

        location /chat {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://app-chat-frontend:8080;
        }

        location ~ ^/chat/(_next/static/|.*\.(png|jpg|jpeg|gif|svg|ico|css|js|woff|woff2|ttf|eot)).*$ {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://app-chat-frontend:8080;
            proxy_buffering on;
            proxy_buffer_size 128k;
            proxy_buffers 4 256k;
            proxy_busy_buffers_size 256k;
            proxy_cache_valid 200 302 1h;
            proxy_cache_valid 404 1m;
            add_header Cache-Control "public, max-age=3600";
            proxy_redirect off;
        }

        location /admin/ {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://admin-management-console:8080;

            # File upload limit
            # Increase max upload size to 1GB for handling large files via Streamlit's file_uploader
            client_max_body_size 1G;
        }

        location /config/ {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://admin-config:8080;
        }

        location /files/ {
            auth_request /oauth2/auth;
            error_page 401 = @error401;
            proxy_pass http://admin-file-viewer:8080/files/;
        }

        location /evaluation_manager/ {
          auth_request /oauth2/auth;
          error_page 401 = @error401;
          proxy_pass http://evaluation-manager-frontend:8080;
        }

        location /evaluation_manager/api/ {
          auth_request /oauth2/auth;
          error_page 401 = @error401;
          proxy_pass http://evaluation-manager-backend:8080/api/;
          proxy_redirect http://evaluation-manager-backend:8080/api/ /evaluation_manager/api/;
        }

        location @error401 {
            return 302 /oauth2/start?rd=$scheme://$http_host$request_uri;
        }
    }
}

