const axios = require("axios");
const { getEntityAsObservable } = context;
const { Subject, from } = require("rxjs");
const { concatMap, tap } = require("rxjs/operators");

const observable = getEntityAsObservable('evaluation-id');

const queue = [];

const processing$ = new Subject();

processing$.pipe(
  concatMap((evaluation_id) => {
    console.log(`\n🔄 Starting processing: ${evaluation_id}`);
    console.log(`📋 Current queue: [${queue.join(', ')}]`);

    return from(axios.post(`${process.env.REQUEST_URL}/${evaluation_id}/execute`))
      .pipe(
        tap({
          next: (response) => {
            if (response.status !== 204) {
              console.warn(`⚠️ Unexpected status for ${evaluation_id}: ${response.status}`);
            } else {
              console.info(`✅ Finished processing: ${evaluation_id}`);
            }
          },
          error: (e) => {
            console.error(`❌ Request failed: ${evaluation_id}`, e.message);
          },
          complete: () => {
            queue.shift();
            console.log(`➡️ Next in queue: ${queue[0] ?? 'None'}`);
          }
        })
      );
  })
).subscribe();

observable.subscribe((evaluation_id) => {
  console.log(`📥 Queued new ID: ${evaluation_id}`);
  queue.push(evaluation_id);
  processing$.next(evaluation_id);
});

